{
  "name": "trace-diag-coding-qwenprobe",
  "version": "1.0.0",
  "description": "Node.js Express server for tracing diagnostics",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "test": "node test.js"
  },
  "dependencies": {
    "express": "^4.18.2"
  },
  "devDependencies": {
    "jest": "^29.7.0"
  }
}

const express = require('express');

const app = express();
const PORT = process.env.PORT || 3000;

// GET /ok endpoint returning JSON {"ok": true}
app.get('/ok', (req, res) => {
  res.json({ ok: true });
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'healthy' });
});

// Start server
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

const app = require('./server');

// Simple test function - in production use Jest or Mocha
async function testOkEndpoint() {
  return new Promise((resolve, reject) => {
    const http = require('http');

    http.get(`http://localhost:${process.env.PORT || 3000}/ok`, (res) => {
      let data = '';

      res.on('data', chunk => {
        data += chunk;
      });

      res.on('end', () => {
        try {
          const json = JSON.parse(data);
          if (json.ok === true) {
            console.log('✓ Test passed: /ok endpoint returns {"ok": true}');
            resolve(true);
          } else {
            console.log('✗ Test failed: /ok endpoint did not return expected value');
            resolve(false);
          }
        } catch (e) {
          console.log('✗ Test failed: Invalid JSON response');
          resolve(false);
        }
      });
    }).on('error', (err) => {
      console.log('✗ Test failed: Could not connect to server');
      reject(err);
    });
  });
}

// Run test if this file is executed directly
if (require.main === module) {
  console.log('Running tests...\n');
  testOkEndpoint()
    .then(() => process.exit(0))
    .catch(() => process.exit(1));
}

module.exports = { testOkEndpoint };

